import {clone,gate,edges,validateGraph,safeUrl,applyRevision,reconstruct,compare,validateStore} from './model.js';
const base=await fetch('/data/curated.json').then(r=>{if(!r.ok)throw Error('Unable to load atlas');return r.json()});validateGraph(base);
const KEY='techtree-state-v1';let storageError='',store={schemaVersion:1,baseVersion:base.asOf,revisions:[],proposals:[]};
try{const saved=localStorage.getItem(KEY);if(saved)store=validateStore(base,JSON.parse(saved));}catch(e){storageError=`Saved state could not be loaded: ${e.message}. The original saved data has been retained. Export it before replacing it.`;}
let tab='map',domain='All fields',status='all',query='',selected='AI-06',focus=false,zoom=1,revision=store.revisions.length,compareVersion=null;
const domains=['AI','Robotics','Materials','Longevity'],colors={AI:'var(--ai)',Robotics:'var(--robot)',Materials:'var(--material)',Longevity:'var(--life)'},icons={AI:'✳',Robotics:'⌘',Materials:'◈',Longevity:'❋'},names={observed:'Observed · scoped result',partial:'Partial evidence',forecast:'Forecast'},$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label,cls='')=>safeUrl(url)?`<a class="${cls}" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${label}</a>`:esc(label);
const current=()=>reconstruct(base,store.revisions,revision);
const nodeName=(g,id)=>g.nodes.find(n=>n.id===id)?.title||id;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function persist(next){validateStore(base,next);try{localStorage.setItem(KEY,JSON.stringify(next));}catch(e){throw Error('Could not save changes. Export a backup or free browser storage; no change was accepted.');}store=next;}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function render(){
 const g=current(),pending=store.proposals.filter(p=>p.state==='pending').length;
 $('#app').innerHTML=`${storageError?`<div class="banner">${esc(storageError)} <button id="raw-export">Export retained save</button></div>`:''}<header><button class="brand" data-tab="map" aria-label="TechTree home"><svg viewBox="0 0 32 38" fill="none" aria-hidden="true"><path d="M16 35V18M16 20L3 7M16 20L29 7M16 29L5 19M16 29L27 19" stroke="currentColor" stroke-width="2"/><circle cx="3" cy="6" r="2" fill="currentColor"/><circle cx="29" cy="6" r="2" fill="currentColor"/></svg>TechTree <small>AN ATLAS OF POSSIBILITY</small></button><nav aria-label="Main navigation">${[['map','The map'],['evidence','Evidence library'],['history','History'],['review',`Review${pending?` (${pending})`:''}`]].map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</nav><div class="header-end"><span class="live"><i></i>Living research atlas</span><button class="primary" id="add-event">＋ Add an event</button></div></header>
 <section class="hero"><div><span class="eyebrow">THE NEXT FRONTIER · 2026—2041</span><h1>The future grows <em>from here.</em></h1><p>Trace the breakthroughs that could reshape our world. Follow the evidence,<br class="desktop-break"> explore what connects, and see what still needs to happen.</p></div><div class="hero-stats"><div class="stat"><strong>24</strong><span>Curated milestones</span></div><div class="stat"><strong>4</strong><span>Connected fields</span></div><div class="stat"><strong>${String(revision).padStart(2,'0')}</strong><span>Map revision</span></div></div></section>
 ${tab==='map'?mapView(g):tab==='evidence'?evidenceView(g):tab==='history'?historyView(g):reviewView(g)}
 <footer class="footer"><span>TECHTREE / A living atlas, grounded in evidence.</span><span>Relationships are hypotheses. Possibility is not a promise.</span></footer><dialog id="event-dialog"></dialog>`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#add-event').onclick=showEvent;
 if($('#raw-export'))$('#raw-export').onclick=()=>download({raw:localStorage.getItem(KEY)},'techtree-retained-save.json');
 bindViews(g);
}
function position(n){const peers=base.nodes.filter(m=>m.domain===n.domain&&m.stage===n.stage),index=peers.findIndex(m=>m.id===n.id);return {x:140+n.stage*190,y:65+domains.indexOf(n.domain)*151+(peers.length>1?index*65:25),compact:peers.length>1};}
function mapView(g){
 const allEdges=edges(g);const related=new Set([selected,...allEdges.filter(e=>e.fromId===selected||e.toId===selected).flatMap(e=>[e.fromId,e.toId])]);
 const matches=n=>(domain==='All fields'||n.domain===domain)&&(status==='all'||n.status===status)&&(!query||`${n.title} ${n.domain} ${n.id} ${n.criteria}`.toLowerCase().includes(query.toLowerCase()));
 const visible=g.nodes.filter(matches);const visibleIds=new Set(visible.map(n=>n.id));
 return `<main class="workspace"><div class="toolbar"><div class="filters" role="group" aria-label="Filter fields">${['All fields',...domains].map(d=>`<button class="chip ${domain===d?'active':''}" data-domain="${d}" style="--accent:${colors[d]||'var(--green)'}">${d!=='All fields'?'<i class="dot"></i>':''}${d}</button>`).join('')}</div><div class="tools"><label class="searchbox"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search milestones" placeholder="Find a milestone…" value="${esc(query)}"></label><select id="status-filter" aria-label="Filter evidence status"><option value="all">All evidence states</option>${Object.entries(names).map(([id,name])=>`<option value="${id}" ${id===status?'selected':''}>${name}</option>`).join('')}</select></div></div><div class="map-shell"><section class="map-area" aria-label="Interactive technology map"><div class="map-meta"><strong>${visible.length} MILESTONES · CONDITIONAL PATHWAYS</strong><span>Layout follows capability, not a predicted date →</span></div><div class="map-scroll"><div class="canvas" style="zoom:${zoom}"><div class="stage-labels"><b>FIELD / PATHWAY</b><span>01 / Foundations</span><span>02 / Emerging evidence</span><span>03 / Capabilities</span><span>04 / Translation</span><span>05 / Possibilities</span></div>${domains.map((d,i)=>`<div class="lane" style="top:${49+i*151}px;--accent:${colors[d]}"><div class="lane-label"><span class="lane-icon">${icons[d]}</span><strong>${d==='AI'?'Artificial intelligence':d}</strong><small>${g.nodes.filter(n=>n.domain===d).length} MILESTONES</small></div></div>`).join('')}<svg class="wires" viewBox="0 0 1100 685" aria-hidden="true"><defs><marker id="arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0 0L5 2.5L0 5" fill="none" stroke="#91aa83" stroke-width=".8"/></marker></defs>${allEdges.filter(e=>visibleIds.has(e.fromId)&&visibleIds.has(e.toId)).map(e=>{const a=position(g.nodes.find(n=>n.id===e.fromId)),b=position(g.nodes.find(n=>n.id===e.toId)),x1=a.x+165,y1=a.y+(a.compact?29:43),x2=b.x,y2=b.y+(b.compact?29:43),highlight=e.fromId===selected||e.toId===selected;return `<path class="wire ${e.kind} ${highlight?'focused':focus?'dim':''}" d="M${x1},${y1} C${x1+75},${y1} ${x2-65},${y2} ${x2},${y2}" marker-end="url(#arrow)"/>`}).join('')}</svg>${visible.map((n,i)=>{const p=position(n);return `<button class="node ${n.status} ${n.id===selected?'selected':''} ${focus&&!related.has(n.id)?'dim':''}" data-node="${n.id}" style="left:${p.x}px;top:${p.y}px;--accent:${colors[n.domain]};--delay:${i*15}ms;${p.compact?'min-height:58px;padding:7px 11px;':''}" aria-pressed="${n.id===selected}" aria-label="${esc(n.title)}, ${esc(names[n.status])}"><span class="node-id">${n.id}<span>${n.status==='observed'?'↗':'◇'}</span></span><span class="node-title" ${p.compact?'style="margin:3px 0;font-size:10px"':''}>${esc(n.title)}</span>${!p.compact?`<span class="node-status"><i class="status-dot"></i>${n.status==='forecast'?'Possible · '+esc(n.forecast?.window||'Undated'):esc(names[n.status])}</span>`:''}</button>`}).join('')}${!visible.length?'<p style="position:absolute;top:150px;left:150px;color:var(--muted)">No milestones match. Try another field or search.</p>':''}<span class="gap-note">Explore a milestone to inspect its open questions ↗</span></div></div><div class="map-footer"><div class="legend"><span><i></i>Required together</span><span><i class="dashed"></i>Alternative route</span><span><i class="dotted"></i>Accelerator</span></div><div class="map-controls"><button id="zoom-out" aria-label="Zoom out">−</button><span>${Math.round(zoom*100)}%</span><button id="zoom-in" aria-label="Zoom in">＋</button><button id="reset-map" aria-label="Reset map view">↺</button></div></div></section><aside class="detail" aria-label="Milestone details">${detailView(g)}</aside></div></main><section class="insight-strip"><span class="insight-mark">↳</span><div><h3>One breakthrough. Many possible futures.</h3><p>Some pathways need several advances together. Others have more than one route. Click a milestone to trace the logic, inspect the primary research, and understand where the uncertainty lives.</p></div><button id="focus-toggle">${focus?'Show the whole map':'Focus selected connections'} ↗</button></section>`;
}
function detailView(g){
 const n=g.nodes.find(n=>n.id===selected)||g.nodes[0];const achieved=new Set(g.nodes.filter(n=>n.status==='observed').map(n=>n.id));const readiness=gate(n,achieved);const sources=n.sourceIds.map(id=>g.sources.find(s=>s.id===id));const downstream=edges(g).filter(e=>e.fromId===n.id),questions=g.openQuestions.filter(q=>q.target===n.id);
 return `<div class="detail-inner" style="--accent:${colors[n.domain]}"><div class="detail-top"><span>${n.domain.toUpperCase()} / ${n.id}</span><span>↗</span></div><h2>${esc(n.title)}</h2><span class="badge ${n.status}"><i class="status-dot"></i>${names[n.status]}</span><h3>What would count</h3><p class="criteria">${esc(n.criteria)}</p>${n.forecast?`<div class="forecast"><span>Scenario window</span><strong>${esc(n.forecast.window)}</strong></div><p style="font-size:10px">${esc(n.forecast.basis)}</p>`:'<div class="forecast"><span>Evidence is scoped</span><strong>Demonstrated result</strong></div>'}<h3>Possible pathways ${n.routes.length?`/ ${n.routes.length}`:''}</h3>${n.routes.length?`<p style="font-size:10px">All milestones in a route must hold. Any complete route can qualify. ${readiness.state==='route-ready'?'A modeled route has observed inputs; this does not establish the target.':'A modeled route is not yet supported by all observed inputs.'}</p>${n.routes.map((r,i)=>`<div class="route ${i?'or':''}"><b>${esc(r.label)}</b><div class="route-nodes">${r.all.map(id=>`<button data-detail-node="${id}" title="${esc(nodeName(g,id))}">${id}</button>`).join('<span style="color:var(--muted);font-size:10px;align-self:center">AND</span>')}</div><p>${esc(r.rationale)}</p><small>Uncertainty: ${esc(r.uncertainty)}</small></div>`).join('')}`:'<p>No prerequisites modeled in this sample. This does not mean none exist.</p>'}${questions.length?`<h3>Unresolved prerequisites</h3>${questions.map(q=>`<div class="uncertainty"><p><b>${esc(q.title)}</b><br>${esc(q.reason)}</p></div>`).join('')}`:''}<h3>What this could help unlock</h3>${downstream.length?[...new Set(downstream.map(e=>e.toId))].map(id=>`<a href="#" class="source-link" data-detail-node="${id}">${esc(nodeName(g,id))} ↗</a>`).join(''):'<p>A possible downstream outcome. Further uses are not mapped yet.</p>'}<h3>Where uncertainty lives</h3><div class="uncertainty"><p>${esc(n.uncertainty)}</p></div>${n.lastReview?`<h3>Latest review</h3><p>${esc(n.lastReview.rationale)}</p><p>Remaining uncertainty: ${esc(n.lastReview.uncertainty)}</p>`:''}<h3>Primary evidence / ${sources.length}</h3>${sources.map(s=>link(s.url,`${esc(s.title)} ↗<small>${esc(s.published)} · ${esc(s.verification)}</small>`,'source-link')+`<p style="font-size:10px">${esc(s.scope)}</p>`).join('')}<p style="font-size:9px;border-top:1px solid var(--line);padding-top:15px">Criteria and connections are editorial hypotheses. Primary sources support the scoped results described above; they do not verify the forecast.</p></div>`;
}
function evidenceView(g){return `<main class="page-content"><div class="view-actions"><span class="eyebrow">PRIMARY RESEARCH / ${g.sources.length} SOURCES</span></div><p>A deliberately small, freshly curated map. Research is linked at the scope it supports. Forecast criteria and pathway logic are editorial proposals, not findings from these papers.</p><div class="cards">${g.sources.map(s=>`<article class="evidence-card"><small>${esc(s.published)} · ${esc(s.checkedAt?.slice(0,10))} CHECKED</small><h3>${esc(s.title)}</h3><p>${esc(s.scope)}</p>${link(s.url,'Read source ↗')}<p style="font-size:10px">${esc(s.verification)}</p><button data-evidence-source="${s.id}">Explore connected milestones →</button></article>`).join('')}</div></main>`;}
function changeDescription(c,g){if(c.kind==='status')return `Evidence state → ${names[c.status]}`;if(c.kind==='forecast')return `Scenario window → ${c.window}`;if(c.kind==='route')return `Add route: ${(c.all||[]).map(id=>nodeName(g,id)).join(' AND ')}`;if(c.kind==='accelerator')return `Add accelerator: ${nodeName(g,c.fromId)} → ${nodeName(g,c.targetId)}`;return `Remove route: ${c.routeId}`;}
function historyView(g){
 let diff='';if(compareVersion!==null){const before=reconstruct(base,store.revisions,compareVersion),d=compare(before,g);diff=`<div class="compare"><span class="eyebrow">REVISION ${compareVersion} → ${revision}</span><h3>${d.nodes.length} milestones changed · ${d.added.length} connections added · ${d.removed.length} removed</h3>${d.nodes.map(n=>{const old=before.nodes.find(o=>o.id===n.id);return `<div class="change-line"><b>${esc(n.title)}</b><br>${esc(names[old.status])} → ${esc(names[n.status])}${JSON.stringify(old.forecast)!==JSON.stringify(n.forecast)?`<br>Window: ${esc(old.forecast?.window||'None')} → ${esc(n.forecast?.window||'None')}`:''}${n.lastReview?`<br>Why: ${esc(n.lastReview.rationale)}<br>Uncertainty: ${esc(n.lastReview.uncertainty)}`:''}</div>`}).join('')}<p>New evidence: ${d.sourcesAdded.map(s=>link(s.url,esc(s.title))).join(', ')||'None'}. Connections and criteria remain hypotheses.</p></div>`;}
 return `<main class="page-content"><div class="view-actions"><span class="eyebrow">A MAP THAT REMEMBERS</span><button class="secondary" id="export">Export backup</button><label class="file-label">Restore backup<input type="file" id="restore" accept="application/json"></label><label>Compare from<select id="compare-from"><option value="">Choose a revision</option>${Array.from({length:store.revisions.length+1},(_,i)=>`<option value="${i}" ${compareVersion===i?'selected':''}>Revision ${i}</option>`).join('')}</select></label><span style="color:var(--muted);font-size:11px">Viewing revision ${revision}</span></div><p>Accepted reviews create a new revision. Earlier states can be reconstructed and compared. Changes stay in this browser; export a backup to move them elsewhere.</p>${diff}<div class="timeline">${[...store.revisions].reverse().map(r=>`<article class="history-card"><div class="revision-head"><div><span class="eyebrow">REVISION ${r.number} · ${esc(r.createdAt.slice(0,10))}</span><h3>${esc(r.event.title)}</h3></div><button class="secondary" data-version="${r.number}">${revision===r.number?'Currently viewing':'View this revision'}</button></div><p>${esc(nodeName(g,r.change.targetId))}: ${esc(changeDescription(r.change,g))}<br>Why: ${esc(r.change.rationale)}<br>Uncertainty: ${esc(r.change.uncertainty)}<br>Reviewer: ${esc(r.event.reviewer)}</p>${link(r.event.url,'Source event ↗')}</article>`).join('')}<article class="history-card"><div class="revision-head"><div><span class="eyebrow">REVISION 0 · 2026-10-30</span><h3>The first curated atlas</h3></div><button class="secondary" data-version="0">${revision===0?'Currently viewing':'View first revision'}</button></div><p>24 measurable milestones across four fields. 11 primary sources checked at abstract level. Conditional pathways and forecast windows are editorial hypotheses. This is a selected evidence baseline, not an exhaustive account of research through 2026.</p></article></div></main>`;
}
function reviewView(g){return `<main class="page-content"><div class="view-actions"><span class="eyebrow">EVIDENCE BEFORE CHANGES</span><button class="secondary" id="latest">View latest map revision</button></div><p>Manual review is fully functional. Paste an announcement or X thread, describe the proposed change, and inspect it here before accepting. The app does not fetch links, read X threads, use an AI service, or verify claims automatically.</p>${store.proposals.length?`<div class="timeline">${[...store.proposals].reverse().map(p=>`<article class="history-card"><span class="eyebrow">${esc(p.state)} · ${esc(p.event.date)}</span><h3>${esc(p.event.title)}</h3><p>${esc(p.event.announcement)}</p><div class="change-line"><b>${esc(nodeName(g,p.change.targetId))}</b><br>${esc(changeDescription(p.change,g))}</div><p>Rationale: ${esc(p.change.rationale)}<br>Uncertainty: ${esc(p.change.uncertainty)}<br>Reviewer: ${esc(p.event.reviewer)}</p>${link(p.event.url,'Inspect original source ↗')}${p.state==='pending'?`<div class="proposal-actions"><button class="primary" data-accept="${p.id}">Accept into new revision</button><button class="secondary" data-reject="${p.id}">Reject proposal</button></div>`:`<p>${p.state==='accepted'?`Recorded in revision ${p.revision}`:'Rejected; map unchanged.'}</p>`}</article>`).join('')}</div>`:'<div class="empty">The review desk is clear.<br><br>Add a real event to propose the first map update.</div>'}</main>`;}
function bindViews(g){
 document.querySelectorAll('[data-domain]').forEach(b=>b.onclick=()=>{domain=b.dataset.domain;render()});
 if($('#search'))$('#search').oninput=e=>{const start=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(start,start)};
 if($('#status-filter'))$('#status-filter').onchange=e=>{status=e.target.value;render()};
 document.querySelectorAll('[data-node],[data-detail-node]').forEach(b=>b.onclick=e=>{e.preventDefault();selected=b.dataset.node||b.dataset.detailNode;render()});
 if($('#focus-toggle'))$('#focus-toggle').onclick=()=>{focus=!focus;render()};
 if($('#zoom-in'))$('#zoom-in').onclick=()=>{zoom=Math.min(1.5,Math.round((zoom+.1)*10)/10);render()};
 if($('#zoom-out'))$('#zoom-out').onclick=()=>{zoom=Math.max(.5,Math.round((zoom-.1)*10)/10);render()};
 if($('#reset-map'))$('#reset-map').onclick=()=>{zoom=1;query='';domain='All fields';status='all';focus=false;render()};
 document.querySelectorAll('[data-evidence-source]').forEach(b=>b.onclick=()=>{selected=g.nodes.find(n=>n.sourceIds.includes(b.dataset.evidenceSource)).id;domain='All fields';query='';status='all';tab='map';focus=true;render()});
 document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{revision=Number(b.dataset.version);tab='map';render();toast(`Viewing revision ${revision}`)});
 if($('#latest'))$('#latest').onclick=()=>{revision=store.revisions.length;tab='map';render()};
 if($('#compare-from'))$('#compare-from').onchange=e=>{compareVersion=e.target.value===''?null:Number(e.target.value);render()};
 if($('#export'))$('#export').onclick=()=>download(store,'techtree-backup.json');
 if($('#restore'))$('#restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('Backup is too large');const next=validateStore(base,JSON.parse(await file.text()));if(!window.confirm('Replace this browser’s review history with this backup? Export your current history first if you need to retain it.'))return;persist(next);revision=store.revisions.length;compareVersion=null;storageError='';render();toast('Backup restored')}catch(err){toast(err.message)}};
 document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>{try{const next=clone(store),p=next.proposals.find(p=>p.id===b.dataset.accept);if(p.state!=='pending')throw Error('Proposal already reviewed');const r={number:next.revisions.length+1,createdAt:new Date().toISOString(),event:p.event,change:p.change};applyRevision(reconstruct(base,next.revisions),r);next.revisions.push(r);p.state='accepted';p.revision=r.number;persist(next);revision=r.number;render();toast(`Accepted. Revision ${r.number} saved.`)}catch(e){toast(e.message)}});
 document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>{try{const next=clone(store);next.proposals.find(p=>p.id===b.dataset.reject).state='rejected';persist(next);render();toast('Proposal rejected. Map unchanged.')}catch(e){toast(e.message)}});
}
function showEvent(){
 const g=reconstruct(base,store.revisions),dlg=$('#event-dialog');
 dlg.innerHTML=`<div class="modal-head"><div><span class="eyebrow">GROW THE ATLAS</span><h2>Add an evidence event</h2></div><button id="close-modal" aria-label="Close event form">×</button></div><div class="modal-body"><p>A source is a starting point. Describe what actually changed and why. This manual workflow saves a proposal for review before the map changes.</p><form id="event-form"><label>Event title<input name="title" required maxlength="180" placeholder="What was reported?"></label><label>Source URL · paper, announcement or X thread<input type="url" name="url" required placeholder="https://…"></label><div class="form-row"><label>Event date<input type="date" name="date" value="2026-10-30" required></label><label>Reviewer name<input name="reviewer" required maxlength="100" placeholder="Who is evaluating this?"></label></div><label>Pasted announcement / evidence summary<textarea name="announcement" required maxlength="12000" placeholder="Include the reported result, experimental setting and limits. Links are not read automatically."></textarea></label><div class="form-row"><label>Milestone<select name="targetId">${g.nodes.map(n=>`<option value="${n.id}" ${n.id===selected?'selected':''}>${esc(n.title)}</option>`).join('')}</select></label><label>Proposed change<select name="kind" id="change-kind"><option value="status">Update evidence state</option><option value="forecast">Revise forecast window</option><option value="route">Add prerequisite route</option><option value="accelerator">Add accelerator</option><option value="remove-route">Remove prerequisite route</option></select></label></div><div id="change-fields"></div><label>Reasoning · why does the evidence support this change?<textarea name="rationale" required maxlength="4000"></textarea></label><label>Remaining uncertainty / what would change your mind?<textarea name="uncertainty" required maxlength="4000"></textarea></label><p class="error" id="form-error" role="alert"></p><div class="form-actions"><small>Nothing changes until accepted in Review.</small><button class="primary" type="submit">Propose for review →</button></div></form></div>`;
 function fields(){const kind=$('#change-kind').value,target=g.nodes.find(n=>n.id===$('[name=targetId]').value);$('#change-fields').innerHTML=kind==='status'?`<label>Evidence state<select name="status">${Object.entries(names).map(([id,label])=>`<option value="${id}" ${id===target.status?'selected':''}>${label}</option>`).join('')}</select></label><label class="checkbox" style="margin-top:12px"><input type="checkbox" name="criteriaConfirmed">For “Observed”, I have checked the milestone’s complete criterion against this source. Partial evidence alone does not establish achievement.</label><p style="font-size:11px;color:var(--muted);line-height:1.6">Criterion: ${esc(target.criteria)}</p>`:kind==='forecast'?'<label>Scenario window<input name="window" required maxlength="60" placeholder="e.g. 2030–2038 · tentative"></label>':kind==='route'?`<label>Route name<input name="label" required maxlength="120" placeholder="A possible route"></label><p style="font-size:11px;color:var(--muted)">All selected prerequisites must hold together. This route is an alternative to existing routes.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:9px">${g.nodes.filter(n=>n.id!==target.id).map(n=>`<label class="checkbox"><input type="checkbox" name="prerequisite" value="${n.id}">${esc(n.title)}</label>`).join('')}</div>`:kind==='accelerator'?`<label>Accelerating milestone<select name="fromId">${g.nodes.filter(n=>n.id!==target.id).map(n=>`<option value="${n.id}">${esc(n.title)}</option>`).join('')}</select></label>`:`<label>Route to remove<select name="routeId" required><option value="">Choose route</option>${target.routes.map(r=>`<option value="${r.id}">${esc(r.label)}</option>`).join('')}</select></label>`;}
 $('#change-kind').onchange=fields;$('[name=targetId]').onchange=fields;fields();$('#close-modal').onclick=()=>dlg.close();
 $('#event-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),id=`event-${crypto.randomUUID()}`,event={id,title:f.get('title'),url:f.get('url'),date:f.get('date'),reviewer:f.get('reviewer'),announcement:f.get('announcement')},change={kind:f.get('kind'),targetId:f.get('targetId'),status:f.get('status'),criteriaConfirmed:f.get('criteriaConfirmed')==='on',window:f.get('window'),label:f.get('label'),all:f.getAll('prerequisite'),fromId:f.get('fromId'),routeId:f.get('routeId'),rationale:f.get('rationale'),uncertainty:f.get('uncertainty')};applyRevision(g,{event,change,createdAt:new Date().toISOString()});const next=clone(store);next.proposals.push({id,event,change,state:'pending',createdAt:new Date().toISOString()});persist(next);dlg.close();tab='review';revision=store.revisions.length;render();toast('Proposal saved for review. The map is unchanged.')}catch(err){$('#form-error').textContent=err.message}};
 dlg.showModal();
}
render();
